export function HormoneChartForPhase({ phase, width }: { phase: string; width: number }) {
  if (phase === 'menstrual') return <HormoneMenstrual width={width} />;
  if (phase === 'follicular') return <HormoneFollicular width={width} />;
  if (phase === 'ovulatory') return <HormoneOvulatory width={width} />;
  return <HormoneLuteal width={width} />;
}
